      "EN4 — Media refers to the materials and/or medium and/or technical means used to create art works (e.g. graphite, oil, watercolour, acrylic, ink, pastel, marble, bronze, wood, fibreglass, plastic, film, video, digital images, performance).",
      "EN5 — Effects refers to the results of an artist using selected media in a particular way, e.g. expressive, visual, texture, movement and scale effects, and effects on the viewer's thoughts, emotions and/or senses brought about by the media and/or processes used."
