     "notes": [
      "EN2 — Carry out a practical investigation (Achieved) involves: developing a statement of the purpose written as a hypothesis linked to a scientific concept or idea; using a method that describes, for a fair test, a range for the independent variable, the measurement of the dependent variable and the control of some other key variables, or, for a pattern seeking or modelling activity, the data that will be collected, range of data/samples and consideration of some other key factors; collecting, recording, and processing data relevant to the purpose of the investigation; interpreting and reporting on the findings; reaching a conclusion based on the student's processed data which is relevant to the purpose of the investigation; identifying and including relevant findings from another source.",
      "EN2 — Carry out an in-depth practical investigation (Merit) involves: using a method that describes, for a fair test, a valid range for the independent variable, the valid measurement of the dependent variable and the control of other key variables with consideration of factors such as sampling bias and sources of errors, or, for a pattern seeking or modelling activity, a valid collection of data with consideration of factors such as sampling bias and sources of errors; collecting, recording, and processing data which enables a trend or pattern (or the absence of a trend or pattern) to be determined; reaching a valid conclusion based on the student's processed data which is relevant to the purpose of the investigation; a discussion of the biological ideas relating to the investigation that is based on the student's findings and those from other source(s).",
      "EN2 — Carry out a comprehensive practical investigation (Excellence) involves justification of the choices made during the sound investigation, ie evaluating the validity of the method or reliability of the data, and explaining the conclusion in terms of the biology ideas relevant to the investigation.",
      "EN3 — A practical investigation is an activity covering the complete investigation process: planning and carrying out the investigation, collecting primary data, processing and interpreting data, and reporting on the investigation. Students may make changes to their initial method as they work through the investigation.",
      "EN4 — Assessment may be based on a stand-alone or an individual investigation that can contribute findings to a larger group or class investigation.",
      "EN6 — With supervision means the teacher provides guidelines such as the context, instructions that specify the requirements for a comprehensive investigation, and broad experimental conditions such as the availability of equipment or chemicals. Students then develop and complete the investigation from these guidelines. Supervision may involve discussion with individual students to clarify their ideas and teachers managing the sharing of findings."
     ],
     "clarifications": {
      "date": "February 2014",
      "points": [
       "Supervision means the teacher may provide the context and broad experimental conditions, may manage the sharing of findings so that enough data is collected across a range of students (or supply the data), and may hold an individual discussion during planning to clarify a student's ideas.",
       "The investigation may be a fair test (e.g. temperature and enzyme activity), a pattern or relationship (e.g. a field study of a population or community) or a model (e.g. diffusion using indicator agar). Each student develops and completes their own single investigation: planning, carrying out, processing and interpreting data, and reporting.",
       "Students may plan and carry out the investigation in a group for manageability, but the teacher must provide written verification (e.g. a class grid) that each student actively participated and recorded their own data.",
       "The purpose must be rewritten as a hypothesis linked to a scientific concept or idea. The conclusion must be based on the trend (or lack of trend) in the processed data in relation to the purpose and hypothesis, not merely a summary of the data.",
       "Findings of others are provided by the teacher (usually two or three sources) and must not guide how the investigation is developed. They may be qualitative (diagrams, graphics from reports or textbooks) or quantitative (graphs, tables, statistics, previous students' grouped data, shared data).",
       "Merit and Excellence require a discussion of biological ideas based on the student's findings and the other source(s). For Excellence, the evidence of a valid conclusion explained by relevant biology may be found in this discussion.",
       "Students may use their portfolio of biological ideas from the context when writing the report. If dual assessed with 91158, each standard needs its own task and assessment schedule (see the 91158 clarification)."
      ]
     },
