      "EN2 — Demonstrate comprehensive understanding (Excellence) involves showing understanding by linking several biological ideas. The linking of ideas may involve justifying, evaluating, comparing and contrasting, or analysing, and must include consideration of the two points appropriate to the chosen context: for one life process over three taxonomic or functional groups — comparing diversity of adaptation in response to the same demand across the groups, and limitations and advantages involved in each feature within each organism; for two related life processes within one group — connections between the two life processes within each organism which enhance the effectiveness of both, and limitations and advantages involved in each feature within each organism.",
