      "EN4 — An adaptation refers to a feature and its function as it enables an organism to carry out a life process and thus occupy a specific ecological niche. It may include structural, behavioural or physiological features, and provides an advantage in the organism's specific habitat and niche.",
      "EN5 — Way of life encompasses how an organism carries out all its life processes, including relationships with other organisms (competition, predation, parasitism, mutualism), reproductive strategies and adaptations to the physical habitat.",
