     "code": "91158",
     "ref": "2.6",
     "credits": 4,
     "version": "Version 2 (published 20 November 2014)",
     "verified": "2026-10-25",
     "title": "Investigate a pattern in an ecological community, with supervision",
     "criteria": {
      "achieved": "Investigate a pattern in an ecological community, with supervision.",
      "merit": "Investigate in-depth a pattern in an ecological community, with supervision.",
      "excellence": "Comprehensively investigate a pattern in an ecological community, with supervision."
     },
     "notes": [
      "EN2 — Investigate (Achieved) involves describing observations or findings, and using those findings to identify the pattern (or absence of a pattern) in an ecological community, relating this pattern to an environmental factor, and describing how the environmental factor might affect chosen species within the community.",
      "EN2 — Investigate in-depth (Merit) involves providing a reason for how or why the biology of one of the chosen species relates to the pattern (or absence of a pattern). The biology involves structural, behavioural or physiological adaptations of the organism which are related to the environmental factor and to an interrelationship with an organism of another species (eg competition, predation, or mutualism).",
      "EN2 — Investigate comprehensively (Excellence) involves using an environmental factor and the biology of interrelated organisms of different species to explain the pattern (or absence of a pattern). The explanation may involve elaborating, applying, justifying, relating, evaluating, comparing and contrasting, and analysing.",
      "EN3 — Investigation involves analysing and interpreting information about the ecosystem, which may come from direct observations, field data, tables, graphs, resource sheets, photographs, videos, websites and/or reference texts.",
      "EN4 — A community pattern may include succession, zonation, stratification, or another distribution pattern in response to an environmental factor. EN5 — Environmental factors may be abiotic and/or biotic.",
      "EN7 — Assessment may be a stand-alone or individual investigation contributing to a group or class investigation; students may interpret their own findings in the light of others' findings and published or historical findings.",
      "EN8 — With supervision means the teacher provides guidelines (context, instructions specifying the requirements for a comprehensive investigation, broad conditions such as equipment and resource material); students develop and complete the investigation from them."
     ],
     "clarifications": {
      "date": "February 2014",
      "points": [
       "Students analyse and interpret primary or secondary data to investigate a pattern (or its absence) in a New Zealand ecological community. Collection of primary data is not assessed, and the standard can be assessed as a written research assignment using secondary data.",
       "Students must relate data on at least two species to the pattern in a quantitative description, explanation or discussion.",
       "Teachers may suggest organisms that interrelate, but students select their own specific pairs; the data students choose for named organisms count towards the evidence at each grade.",
       "Analysis should be at species level (e.g. acorn barnacles), not groups (e.g. \"mussels, barnacles or green algae\"), so the pattern can be linked to species-specific adaptations and environmental factors.",
       "If dual assessed with 91153, each standard needs its own task and assessment schedule and the dual assessment must be stated in the task; there must be enough data to explain an interrelationship between at least two species. If 91158 is assessed in a different context, resources and methods may be provided, but that context cannot then be used for 91153."
      ]
     },
