     "notes": [
      "EN3 — Achieved typically involves: planning for a guided business activity; carrying out a first cycle; reviewing the first cycle; stating refinements; carrying out a second cycle of the refined activity; stating business knowledge relevant to the activity; stating a Māori business concept(s) where relevant; stating how well the activity was performed in the second cycle; comparing the outcome with the original planned activity; making the changes arising from the review with the aim of making improvement(s).",
      "EN4 — Merit typically involves: planning in-depth; using reasoned explanations to refine the activity; including business knowledge (and Māori business concepts where relevant) to support explanations; reviewing in-depth how well the activity was performed in the second cycle; comparing the outcome of the second cycle to the business plan made after the review of the first cycle.",
      "EN5 — Excellence typically involves: comprehensive planning; integrating business knowledge (and Māori business concepts where relevant) to fully support explanations; refining the business plan for the future.",
      "EN6 — A community context means the business activity must have a community well-being focus and operate in the wider community. Well-being refers to improving the social, mental or physical health of a community or improving community cohesion.",
      "EN6 — With guidance refers to teacher assistance given in relation to the business activity and ethical aspects.",
      "EN6 — Review means comparing the outcome of the business activity with the original planned business activity; review-in-depth means comparing the outcome of the second cycle to the business plan made after the review of the first cycle; refine means making the changes arising from the review with the aim of making improvement(s).",
      "EN6 — A business activity refers to the production of a good or service."
     ],
