       "For Excellence, students refine the plan again; this third version should be clear enough for an outside party to implement in future.",
       "Reviews must report progress towards SMART objectives — especially sales or profit targets — the community focus and other planned outcomes, and link back to the planning. Business knowledge should be evident in planning and reviews at every grade.",
       "A plan at Achieved that lacks Merit-level detail and business knowledge is unlikely to support an in-depth review; a Merit plan is unlikely to support a comprehensive review."
