      "Implications named in a list (privacy, accessibility, ethics) but not analysed in relation to this proposal.",
      "Perspectives or end-user survey data that look invented or generic (AI-generated personas, round-number results with no raw data); statistics and URLs that need checking — mark as 'check', never as 'fabricated'.",
