      "EN3 — A practical Earth and Space Science investigation (Achieved) involves: a statement of purpose arising from a scientific context; developing a method that describes ranges for key variables, how key variables are measured, the management of some other variables, and the collection of raw data; collecting raw data consistent with the method; recording and processing raw data relevant to the purpose; interpreting the processed data to draw a conclusion related to the purpose of the investigation; describing the Earth and Space Science related to the investigation; reporting on the investigation.",
      "EN3 — An in-depth practical investigation (Merit) is further developed by: confirming the original method or refining the method to increase the validity and reliability of collected data by the development of valid ranges for the key variables, valid measurement of key variables, valid management of other variables, and reliable collection of raw data; interpreting the processed data to draw a VALID conclusion related to the purpose; EXPLAINING the Earth and Space Science related to the investigation.",
      "EN3 — A comprehensive practical investigation (Excellence) is further developed by: explaining how the method allowed for reliable data to be collected; explaining in detail the Earth and Space Science related to the investigation, linking the results, interpretation and conclusion to the relevant science.",
      "EN4 — Conditions of Assessment for this standard are published by the Ministry of Education (NCEA on TKI)."
