       "The investigation must have a valid purpose, identify the independent and dependent variables, identify how other key variables will be managed, and allow raw data consistent with the method to be collected.",
       "No template should be supplied — that would be over-direction.",
       "Data must be processed so that a conclusion can be drawn; processing can include graphs, tables or statistical analysis.",
       "Students must carry out the investigation themselves to collect primary evidence, and use their findings to describe the related Earth and Space Science. This component must be covered before a final grade is awarded.",
