      "EN2 — Investigate comprehensively (Excellence) is further developed by: selecting and processing information that provides INTEGRATED LINKS between conditions of the extreme environment and biological adaptations or technological modifications; JUSTIFYING, using the processed information, how the biological adaptations or technological modifications allow the organism(s) to survive the conditions of the extreme environment.",
      "EN3 — Organisms can be the same or different species, including humans.",
