      "EN2 — Comprehensive (Excellence) involves: fully explaining the spatial and/or temporal variation in the urban pattern; fully explaining the factors and/or circumstances that contribute to the spatial and/or temporal variation; integrating geographic terminology and supporting evidence from a case study.",
      "EN3 — An urban pattern is the spatial and/or temporal variation created in a city. Factors and circumstances may include elements, events and perceptions that contribute to the pattern. Patterns studied may include crime, transport networks, education networks, gentrification, urban sprawl and retail development."
