      "points": [
       "Version 4 removed the specific reference to a geographic concept and added a requirement for geographic terminology. Insight is no longer required for Excellence.",
       "One city must be selected as the case study. The context decides whether the focus is the CBD or the wider urban area (e.g. graffiti may need only the CBD; transport networks need the greater urban area).",
       "The standard has two key aspects: (1) the pattern and the circumstances/factors that contribute to it, and (2) a variation in that pattern and its contributing circumstances/factors. The assessment task must clearly identify both.",
       "Spatial and temporal patterns can both be used. Spatial patterns may be described as concentrated or dispersed; temporal patterns as constant or cyclic.",
       "Students could show the pattern and a variation using city maps, graphs, timelines and similar tools.",
       "Case-study evidence and geographic terminology need to be used throughout the response."
      ]
