      "EN2 — In-depth (Merit) involves: accurately presenting spatial, statistical, and visual data, using the correct geographic conventions and terminology; explaining findings, in detail, incorporating the relevance of geographic concepts; providing a conclusion, in detail, that relates to the aim of the research; explaining, in detail, the strength(s) and weakness(es) of the research process and how these affect the validity of the research findings and/or conclusions.",
      "EN2 — Comprehensive (Excellence) involves: accurately and effectively presenting spatial, statistical, and visual data, using the correct geographic conventions and terminology; fully explaining findings, incorporating the relevance of geography concepts; fully explaining the strength(s) and weakness(es) of the research process, and how these affect the validity of the research findings and/or conclusions; discussing ways the research process could be improved.",
      "EN3 — Geographic research is an investigation of a particular area or environment and always has a spatial element. With guidance refers to students being supported to conduct geographic research, which may include planning (e.g. setting an aim, identifying relevant concepts), presenting findings with correct conventions and terminology, and evaluating the research process.",
      "EN4 — Primary data must be included: data collected by the student, individually or as a group (observing, measuring, sketching, photographing, surveys, questionnaires, interviews). Secondary data may be included, but primary data collection must be the main focus.",
