     "title": "Analyse issues related to sexuality and gender to develop strategies for addressing the issues",
     "criteria": {
      "achieved": "Analyse issues related to sexuality and gender to develop strategies for addressing the issues.",
      "merit": "Analyse in depth, issues related to sexuality and gender to develop strategies for addressing the issues.",
      "excellence": "Analyse comprehensively, issues related to sexuality and gender to develop strategies for addressing the issues."
     },
     "notes": [
      "EN2 — Analyse (Achieved) involves: explaining influences on gender and sexual identity; recommending a relevant combination of personal, interpersonal and societal strategies to address the issues, which reflect the values of social justice.",
      "EN2 — Analyse in depth (Merit) involves explaining: why or how influences impact on gender and sexual identity; how strategies to address issues reflect the values of social justice.",
      "EN2 — Analyse comprehensively (Excellence) involves engaging critically with the evidence to explain: how recommended strategies to address issues reflect the values of social justice; the interrelationships between the personal, interpersonal and societal aspects.",
      "EN3 — Influences on gender and sexual identity can relate to individuals and/or groups and include a relevant selection of personal (e.g. biological), interpersonal (e.g. family or friends) and/or societal (e.g. culture, media) considerations. Strategies that reflect the values of social justice require personal and collective actions that contribute to a societal good and benefit the well-being of individuals, groups and communities."
     ],
     "clarifications": {
      "date": "December 2018",
      "points": [
       "Gender identity is a person's sense of being male, female, or gender queer/non-binary and the characteristics society associates with each; it can cover cultural, political, economic, social and personal aspects.",
       "Sexual identity is how a person understands their sexuality and expresses it to others, including orientation, behaviour, diversity, and personal and social dimensions.",
       "Students explain at least one factor for gender identity AND at least one for sexual identity: describe the factor, justify how it influences identity, and explain the resulting issues.",
       "Students recommend a suitable combination of personal, interpersonal and societal strategies; for each, describe what it involves and explain how it addresses the issues, supports well-being, and reflects social justice (fairness, inclusiveness, non-discrimination).",
       "Merit: more detailed account of how and why factors shape identity; strategy explanations clearly address outcomes that promote social justice.",
       "Excellence: critical engagement with evidence (from task resources or own learning); thoughtful reasoning showing perceptive understanding; strategies deliberately chosen; explanation of how personal, interpersonal and societal aspects connect (factors interacting or strategies connecting)."
      ]
     },
     "nmr": [],
     "exemplars": [
      {
       "grade": "Not Achieved",
       "text": "High Not Achieved (Harry scenario with music-video resources): one factor for each identity described with evidence; strategies recommended.",
       "miss": "Not Achieved because it does not explain how or why the factors influence identity, and the 'societal' action is interpersonal in nature (a support group is not particularly suitable)."
      },
      {
       "grade": "Achieved",
       "text": "High Achieved: one factor for each identity described using evidence and resource extracts, with some explanation of how each influences identity; resulting social injustices briefly described; strategies recommended for a sexual identity situation.",
       "miss": "Not Merit because how and why the factors influence identity needed more detail, and strategy outcomes for social justice were undeveloped."
      },
      {
       "grade": "Merit",
       "text": "High Merit: family and cultural expectations (gender identity) and personal attitudes, values and beliefs (sexual identity) explained; resulting issues where social justice is not encouraged described; strategies explained with some reference to social justice outcomes.",
       "miss": "Not Excellence because influences needed more critical explanation linked to evidence, interrelationships between strategies were underdeveloped, and social justice outcomes needed more detail."
      },
      {
       "grade": "Excellence",
       "text": "Low Excellence: two factors explained in detail with evidence, including how and why each influences identity and the social injustices arising; strategies clearly linked to each other and more critical in addressing injustice. A more secure Excellence would tie the media influence to the specific videos, use examples beyond the scenario, and justify social justice outcomes in more depth."
      }
     ],
