     "title": "Use statistical methods to make an inference",
     "criteria": {
      "achieved": "Use statistical methods to make an inference.",
      "merit": "Use statistical methods to make an inference, with justification.",
      "excellence": "Use statistical methods to make an inference, with statistical insight."
     },
     "notes": [
      "EN2 — Use statistical methods to make an inference (Achieved) involves showing evidence of using each component of the statistical enquiry cycle.",
      "EN2 — With justification (Merit) involves linking components of the statistical enquiry cycle to the context, and/or to the populations, and referring to evidence such as sample statistics, data values, trends, or features of visual displays in support of statements made.",
      "EN2 — With statistical insight (Excellence) involves integrating statistical and contextual knowledge throughout the statistical enquiry cycle, and may involve reflecting on the process, or considering other explanations for the findings.",
      "EN3 — The statistical enquiry cycle involves: posing an appropriate investigative comparison question from a given set of population data; selecting random samples; selecting and using appropriate displays and measures; discussing sample distributions; discussing sampling variability, including the variability of estimates; making an inference; communicating findings in a conclusion.",
      "EN1 — Related to Level 7 objectives: investigations using existing data sets, evaluating sampling and data collection methods, using contextual knowledge, exploratory data analysis and statistical inference; making inferences from surveys using sample statistics as point estimates and recognising the effect of sample size on variability."
     ],
     "clarifications": {
      "date": "July 2019 ('Problem', 'Analysis' and 'Conclusion' sections updated)",
      "points": [
       "The assessment activity must include enough contextual knowledge to give students opportunities for statistical insight.",
       "Problem: the investigative question must involve a comparison and specify the variable, the population groups being compared, the population parameter (the median) and the direction of the comparison (e.g. is the median hand-luggage weight on 2015 Air NZ Auckland–Wellington flights less than for flights from overseas to Wellington?).",
       "Plan and data: students select random samples and use them to infer about the populations. The data set must reflect a real context and be large enough to be treated as the population. Students must show they understand the population the sample is drawn from.",
       "Analysis: for Merit and Excellence, informal confidence intervals must be interpreted in context (e.g. 'I am pretty sure that for all Air New Zealand flights in 2015…').",
       "Discussion of sample distributions must be about the distributions of the variable (not just the groups), include numerical values and units, and be based on visual evidence; sample statistics may support it.",
       "Conclusion: the inference must answer the investigative question, be consistent with the analysis and show the uncertainty involved. Non-overlapping intervals: 'pretty sure' one median is greater/less. Overlapping intervals: not enough evidence to make the call.",
       "Students must show understanding of sampling variability — another sample could give different statistics and intervals, but the intervals are still likely to capture the population parameter. Considering only sample size is NOT sufficient."
      ]
     },
