     "criteria": {
      "achieved": "Conduct an experiment to investigate a situation using statistical methods.",
      "merit": "Conduct an experiment to investigate a situation using statistical methods, with justification.",
      "excellence": "Conduct an experiment to investigate a situation using statistical methods, with statistical insight."
     },
     "notes": [
      "EN2 — Achieved involves showing evidence of using each component of the investigation process.",
      "EN2 — With justification (Merit) involves: linking components of the process of investigating a situation by experiment to the context; explaining relevant considerations in the investigation process; supporting findings with statements which refer to evidence gained from the experiment.",
      "EN2 — With statistical insight (Excellence) involves: integrating statistical and contextual knowledge throughout the investigation process, which may involve reflecting on the process, or considering other relevant variables.",
      "EN3 — The process of investigating a situation by experiment involves: posing an investigative question about a given experimental situation; planning the experiment by determining appropriate variables and measures and determining data collection and recording methods; conducting the experiment and collecting data; selecting appropriate displays and measures; discussing displays and measures; communicating findings in a conclusion."
     ],
     "clarifications": {
      "date": "July 2019 (first section renamed 'Question, Plan and Conclusion')",
      "points": [
       "The assessment activity must include enough contextual knowledge to allow for statistical insight.",
       "Students may be given the experimental situation. The experiment must involve an intervention, and the investigative question must be about the effect of that intervention (e.g. jumping off the non-dominant vs dominant foot and horizontal distance).",
       "Students decide for themselves the intervention, the variables to measure and how to measure them.",
       "At every grade, the conclusion must include a suggestive (causal) inference — e.g. the dominant foot appears to cause a longer jump for the experimental group.",
       "Two independent groups: units randomly assigned to control and treatment groups; dot plots and/or box plots for each group; compare shape, shift, centre, spread and unusual features, linked to the treatment.",
       "Paired comparison: before/after measurements on the same unit; displays must keep the link between observations and units (arrow plot, or dot/box plot of differences); discuss how the treatment effect varies between units.",
       "Merit: link each component to the context, consider related variables and their possible effects in the plan, and support findings with experimental evidence.",
       "Excellence: integrate statistical and contextual knowledge — consider related variables and their effects, plan to keep data consistent, and use context to explain the findings."
      ]
     },
