      "EN2 — With justification (Merit) involves supporting the comments on the features and findings with reference to statistical evidence and the statistical processes used to carry out the survey.",
      "EN2 — With statistical insight (Excellence) involves integrating statistical and contextual information to assess the quality of the report in terms of its purpose.",
      "EN3 — Features of a survey include: population measures and variables; sampling methods; survey methods; sampling and possible non-sampling errors; sample size.",
