      "EN2 — Extended abstract thinking (Excellence) involves one or more of: devising a strategy to investigate or solve a problem; identifying relevant concepts in context; developing a chain of logical reasoning, or proof; forming a generalisation; AND ALSO using correct mathematical statements, or communicating mathematical insight.",
      "EN3 — Problems are situations that provide opportunities to apply knowledge or understanding of mathematical concepts and methods. Situations will be set in real-life or mathematical contexts.",
