       "When forming a system of equations as evidence of a method, one equation must be non-linear.",
       "Correctly solving a GIVEN pair of simultaneous equations is not evidence. Forming and using a pair of simultaneous equations, or interpreting their solution in context, is.",
       "Communication — Achieved: indicate what the calculated answer represents. Merit: clearly indicate what is being calculated and link solutions to the context. Excellence: clear communication with correct mathematical statements and explanation of decisions made."
