   "discipline": "Level 2 Physical Education internal assessment is judged on the quality of the student's thinking about their own physical activity experience: explaining how and why (Achieved), explaining fully with interrelationships, evidence or in-depth investigation (Merit), and evaluating or examining critically with supported judgements (Excellence). Evidence must be grounded in what the student personally did, trained, led or experienced; volume, the number of principles or strategies covered, and physical performance are never the criteria.",
   "parallelHint": "a different physical activity, skill, event, group or outdoor context (e.g. a basketball lay-up rather than a volleyball serve, a waka ama crew rather than a netball team) and different principles or strategies",
   "privacyNote": "Students' personal reflections in Physical Education can include health, injury, fitness, body-image, family and whānau information. Use only what is needed to judge the evidence, do not repeat personal details in feedback or reports, and treat any disclosure of harm or wellbeing concern through the school's pastoral process, not as assessment evidence.",
