     "title": "Demonstrate understanding of how and why biophysical principles relate to the learning of physical skills",
     "criteria": {
      "achieved": "Demonstrate understanding of how and why biophysical principles relate to the learning of physical skills.",
      "merit": "Demonstrate in-depth understanding of how and why biophysical principles relate to the learning of physical skills.",
      "excellence": "Demonstrate comprehensive understanding of how and why biophysical principles relate to the learning of physical skills."
     },
     "notes": [
      "EN2 — Demonstrate understanding (Achieved) involves explaining how and why biophysical principles relate to the learning of physical skills.",
      "EN2 — Demonstrate in-depth understanding (Merit) involves explaining fully how and why biophysical principles relate to the learning of physical skills, as well as the interrelationship between biophysical principles.",
      "EN2 — Demonstrate comprehensive understanding (Excellence) involves evaluating how and why biophysical principles relate to the learning of physical skills, as well as the interrelationship between the biophysical principles.",
      "EN3 — Students are expected to have applied biophysical principles in a skill or physical activity setting; this experience supports the required depth of understanding.",
      "EN4 — Biophysical principles are aspects of exercise science: functional anatomy, biomechanical principles, skill learning, aspects of sport psychology.",
      "EN5 — Functional anatomy is the anatomy knowledge needed to understand biomechanics, e.g. how major muscles move bones at joints and how joint actions are described.",
      "EN6–8 — Biomechanics may include inertia, momentum, stability and balance, centre of mass, force, force summation, levers, projectile motion, basic performance appraisal; skill learning may include stages of learning, types of practice, factors affecting learning; sport psychology may include self-talk, visualisation, mental rehearsal, routines, arousal control, goal setting, confidence, concentration."
     ],
     "clarifications": {
      "date": "December 2017",
      "points": [
       "Students must apply biophysical principles to the learning of physical skills. At least TWO principles must be demonstrated (e.g. skill learning, sport psychology, biomechanics, functional anatomy).",
       "Focusing on the most relevant principles allows more depth of explanation or evaluation.",
       "Functional anatomy is part of understanding biomechanics and must be explained, not shown by naming joints or listing muscles.",
       "Achieved: what the principle is, how and why each principle relates to learning the skill, and specific examples from the student's own experience. For verbal responses the teacher's annotation should be summarised to reflect the criteria.",
       "Merit: each principle explained in detail, and a clear interrelationship between principles explained (e.g. force summation with feedback).",
       "Excellence: evaluate how and why the principles relate to learning the skill and evaluate a clear interrelationship; may include which principle(s) were most or least beneficial, with reasons and specific examples, and changes made to improve the learning of the skill."
      ]
     },
