       "Achieved: explain the intended aims/purpose, the planning, the implementation, the outcomes for participants and how they relate to the planned aim — clearly linking planning, intended outcomes and actual outcomes.",
       "Comprehensive examination evaluates the implementation, the outcomes and how they relate to the aim; judgements cover what worked or did not, what could be done or changed in future to achieve the intended outcomes, and supporting evidence from the event.",
       "Evidence (personal accounts, photographs, participant or stakeholder evaluations) is required to support the in-depth examination for Merit and Excellence.",
